"""Migration of the Meridian CRM 4.2 case escalation nightly job."""

from datetime import datetime


def _date_diff(today: str, open_date: object) -> int:
    """Return whole calendar days today - open_date under legacy semantics."""
    if today == "00000000" or not open_date or open_date == "00000000":
        return 0

    open_date_text = str(open_date)
    if len(today) != 8 or len(open_date_text) != 8:
        return 0

    try:
        current = datetime.strptime(today, "%Y%m%d").date()
        opened = datetime.strptime(open_date_text, "%Y%m%d").date()
    except ValueError:
        return 0

    return (current - opened).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return auto-escalation workflow events for overdue live support cases."""
    events: list[dict] = []

    for case in sorted(cases, key=lambda row: str(row.get("CASE_ID", ""))):
        if case.get("DEL_FLG") == "Y":
            continue

        status = case.get("STAT_CD")
        age_days = _date_diff(today, case.get("OPEN_DT"))

        if status == "N" and age_days >= 2:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )

        if status == "A" and case.get("ESC_FLG") != "Y" and age_days >= 7:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )

    return events
